<template>
  <!-- Port of XMCL MultiplayerDesktop/Multiplayer views for the local API. -->
  <section class="xmcl-multiplayer"><header><div><div class="eyebrow">MULTIPLAYER</div><h3>多人游戏</h3><p>保存常用服务器并从当前实例直接加入。</p></div><q-btn color="primary" icon="add" label="添加服务器" @click="add"/></header><div class="xmcl-server-grid"><article v-for="server in servers" :key="server.id" class="xmcl-server-card"><div class="xmcl-server-icon"><q-icon name="dns" size="30px"/></div><div class="xmcl-server-info"><strong>{{ server.name }}</strong><small>{{ server.address }}</small><span v-if="server.description">{{ server.description }}</span></div><div class="row q-gutter-xs"><q-btn flat round icon="play_arrow" :disable="busy || !instance" @click="join(server)"/><q-btn flat round icon="open_in_new" @click="open(server)"/><q-btn flat round color="negative" icon="delete" @click="remove(server)"/></div></article><div v-if="!servers.length" class="xmcl-multiplayer-empty"><q-icon name="hub" size="54px"/><h5>还没有保存的服务器</h5><p>添加地址后可以从实例主页快速启动。</p></div></div><q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner></section>
</template>
<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
const props=defineProps<{instance:any;busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();const servers=ref<any[]>([]),error=ref('');const key='xmcl-multiplayer-servers';
function load(){try{servers.value=JSON.parse(localStorage.getItem(key)||'[]');}catch{servers.value=[];}}
function save(){localStorage.setItem(key,JSON.stringify(servers.value));}
function add(){const name=window.prompt('服务器名称');const address=window.prompt('服务器地址，例如 play.example.com:25565');if(!name||!address)return;servers.value.push({id:crypto.randomUUID(),name,address});save();}
function remove(s:any){servers.value=servers.value.filter(x=>x.id!==s.id);save();}
async function open(s:any){const url=`https://minecraft-mp.com/server/?address=${encodeURIComponent(s.address)}`;try{await props.execute('desktop.open-url',{url});}catch(e){error.value=String(e);}}
async function join(s:any){if(!props.instance)return;const address=s.address.includes(':')?s.address:`${s.address}:25565`;const [host,port]=address.split(':');try{await props.execute('instance.launch',{instance:props.instance.id,server:host+':'+port});}catch(e){error.value=String(e);}}
watch(()=>props.instance,load);onMounted(load);
</script>
<style scoped>.xmcl-multiplayer{max-width:1150px;margin:0 auto;padding:30px}.xmcl-multiplayer>header{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:26px}.xmcl-multiplayer h3{margin:4px 0;font-size:30px}.xmcl-multiplayer p{margin:0;color:rgba(255,255,255,.56)}.eyebrow{font-size:11px;letter-spacing:.14em;color:#a5b4fc;font-weight:700}.xmcl-server-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}.xmcl-server-card{display:flex;align-items:center;gap:12px;padding:16px;border-radius:16px;background:rgba(35,35,42,.76);border:1px solid rgba(255,255,255,.1);transition:.2s}.xmcl-server-card:hover{border-color:rgba(129,140,248,.6);transform:translateY(-2px)}.xmcl-server-icon{width:52px;height:52px;display:flex;align-items:center;justify-content:center;border-radius:14px;background:rgba(129,140,248,.2);color:#a5b4fc}.xmcl-server-info{flex:1;min-width:0;display:flex;flex-direction:column}.xmcl-server-info strong,.xmcl-server-info small,.xmcl-server-info span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.xmcl-server-info small{color:#a5b4fc}.xmcl-server-info span{font-size:12px;color:rgba(255,255,255,.48);margin-top:5px}.xmcl-multiplayer-empty{grid-column:1/-1;text-align:center;padding:90px 20px;color:rgba(255,255,255,.5)}.xmcl-multiplayer-empty h5{margin:14px 0 5px;color:#fff}.xmcl-multiplayer-empty p{margin:0}@media(max-width:650px){.xmcl-multiplayer{padding:18px 12px}.xmcl-multiplayer>header{display:block}.xmcl-multiplayer>header .q-btn{margin-top:16px}}
</style>
